def universal_mission_revision(config: Any) -> str:
    """Enabled Relay binds revision 10; unchanged OFF plans retain revision 9."""
    normalized = normalize_universal_config(config)
    return UNIVERSAL_RELAY_MISSION_REVISION if normalized.get("cookie_relay", {}).get("enabled") is True else UNIVERSAL_MISSION_REVISION


def _cookie_relay_detector_identity() -> dict[str, str]:
    """Bind enabled Relay's executable calibration into its frozen Plan.

    This helper is deliberately lazy and uncached: legacy OFF plans require no
    detector data, while changing the installed signatures invalidates an ON
    checkpoint when the runtime recompiles its authority before input.
    """
    from visionstudio_cookie_relay import DETECTOR_VERSION

    path = Path(__file__).resolve().parent / "data" / "cookie-relay-signatures.json"
    try:
        signatures = path.read_bytes()
    except OSError as exc:
        raise UniversalMissionError("Cookie Relay visual signatures are unavailable") from exc
    return {
        "version": DETECTOR_VERSION,
        "signatures_sha256": hashlib.sha256(signatures).hexdigest(),
    }

